-- 関数の実行権限の閉世界。関数は作った瞬間に PUBLIC へ実行権限が開き、プラットフォームの既定では
-- 面のロールにも名指しで付く。`revoke … from public` は後者に触れないので、ここで宣言の外の関数
-- (手続き・集約を含む)から面のロールと PUBLIC の実行権限を外す。面のロールから呼べるのは、土台の関数・隠し列の
-- 述語・RLS 補助関数(いずれも自分の宣言の migration が `grant execute` を持つ)だけである。
-- 書き込みの RPC は実行者を引数で信じるので、面のロールから呼べてはならない。
--
-- 次の作成主体はプラットフォームが持つ役で、この migration からは既定の実行権限を閉じられない。
-- この役が後から作る関数の既定は閉じていない —— 保証は、流す時点の一覧の剥奪と、閉世界の突合
-- (function-acl-parity)が持つ。
--   supabase_admin: プラットフォームが拡張や内部の関数を作る役。migration を流す接続(postgres)はこの役のメンバーではなく、既定の付与を書き換えられない。
do $$
declare
    fn record;
    creator text;
    schema_name text;
    leftovers text;
begin
    for fn in
        select p.oid::regprocedure as signature
          from pg_proc p
          join pg_namespace n on n.oid = p.pronamespace
         where n.nspname in ('public', 'api')
           and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
           and not exists (
               select 1
                 from unnest(array[
                       'api.actor_id()',
                       'api.can_see_holds_note(public.holds)',
                       'api.can_see_patrons_card_number(public.patrons)',
                       'api.is_end_user()',
                       'api.session_alive()',
                       'public.is_librarian()',
                       'public.is_patron()'
                 ]::text[]) as declared(identity)
                where to_regprocedure(declared.identity)::oid = p.oid
           )
    loop
        execute format('revoke all on routine %s from public, anon, authenticated', fn.signature);
    end loop;

    -- 新しい関数(手続き・集約を含む)の実行権限は、作った役の既定から決まる。既定は全体の付与と、スキーマごとの
    -- 付与の 2 層で、どちらも役ごとの別の行であり、加算で効く(片方を外してももう片方は残る)。関数を作る役
    -- (と実行した役)ごとに、全体からも各スキーマからも PUBLIC と面のロールの両方を外す(宣言する関数は
    -- 自分の migration で `grant execute` する)。実在するのに書き換えられない役があれば止める。
    for creator in select distinct unnest(array['postgres', current_user::text]::text[]) loop
        if not exists (select 1 from pg_roles where rolname = creator) then
            continue;
        end if;
        if not pg_has_role(current_user, creator::name, 'MEMBER') then
            raise exception '作成主体 % は実在しますが、この接続の役はそのメンバーではありません。この役の既定の実行権限を外せないので止めます(外す権限のある役で流してください)', creator using errcode = '42501';
        end if;
        execute format('alter default privileges for role %I revoke execute on functions from public, anon, authenticated', creator);
        foreach schema_name in array array['public', 'api'] loop
            if to_regnamespace(schema_name) is not null then
                execute format('alter default privileges for role %I in schema %I revoke execute on functions from public, anon, authenticated', creator, schema_name);
            end if;
        end loop;
    end loop;

    -- プラットフォームが持つ作成主体は migration の責務の外だが、接続の役がそのメンバーなら既定も外す
    -- (メンバーでなければ触れない。止めない —— 下の事後条件が、残った付与を名指しして止める)。
    for creator in select unnest(array['supabase_admin']::text[]) loop
        if exists (select 1 from pg_roles where rolname = creator)
            and pg_has_role(current_user, creator::name, 'MEMBER') then
            execute format('alter default privileges for role %I revoke execute on functions from public, anon, authenticated', creator);
            foreach schema_name in array array['public', 'api'] loop
                if to_regnamespace(schema_name) is not null then
                    execute format('alter default privileges for role %I in schema %I revoke execute on functions from public, anon, authenticated', creator, schema_name);
                end if;
            end loop;
        end if;
    end loop;

    -- 事後条件: 宣言の外の関数(拡張が持つものを除く)に、面のロールか PUBLIC の実行権限が 1 つでも残って
    -- いれば止める。外せなかった付与(所有者でない役が作った関数など)を黙って通さない。
    select string_agg(format('%s → %s', q.signature, q.grantee), ', ' order by q.signature, q.grantee)
        into leftovers
      from (
        select p.oid::regprocedure::text as signature,
               (case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee)::text end) as grantee
          from pg_proc p
          join pg_namespace n on n.oid = p.pronamespace
          cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
         where n.nspname in ('public', 'api')
           and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
           and not exists (
               select 1
                 from unnest(array[
                       'api.actor_id()',
                       'api.can_see_holds_note(public.holds)',
                       'api.can_see_patrons_card_number(public.patrons)',
                       'api.is_end_user()',
                       'api.session_alive()',
                       'public.is_librarian()',
                       'public.is_patron()'
                 ]::text[]) as declared(identity)
                where to_regprocedure(declared.identity)::oid = p.oid
           )
           and a.privilege_type = 'EXECUTE'
           and (a.grantee = 0 or pg_get_userbyid(a.grantee)::text = any(array['anon', 'authenticated']::text[]))
    ) q;
    if leftovers is not null then
        raise exception '宣言の外の関数に面のロールか PUBLIC の実行権限が残っています(外せなかった付与です。所有者の役で外すか、関数を宣言に加えてください): %', leftovers using errcode = '42501';
    end if;
end
$$;

-- sequence の権限の閉世界。表の revoke は sequence に効かず、プラットフォームの既定は面のロールに usage / select / update を
-- 与える(nextval / setval で採番を動かせる)。面のロールは表へ直に書かない(書き込みは全部 security definer の RPC を通る)ので、
-- 計画のスキーマの全 sequence から面のロールと PUBLIC の権限を外し、新しい sequence の既定の付与も作成主体ごとに閉じる。
-- 事後条件: 面のロールか PUBLIC の権限が 1 つでも残っていれば止める。
do $$
declare
    seq record;
    creator text;
    schema_name text;
    leftovers text;
begin
    for seq in
        select c.oid::regclass as name
          from pg_class c
          join pg_namespace n on n.oid = c.relnamespace
         where c.relkind = 'S'
           and n.nspname in ('public', 'api')
           and not exists (select 1 from pg_depend d where d.classid = 'pg_class'::regclass and d.objid = c.oid and d.deptype = 'e')
    loop
        execute format('revoke all on sequence %s from public, anon, authenticated', seq.name);
    end loop;

    for creator in select distinct unnest(array['postgres', current_user::text]::text[]) loop
        if not exists (select 1 from pg_roles where rolname = creator) then
            continue;
        end if;
        if not pg_has_role(current_user, creator::name, 'MEMBER') then
            raise exception '作成主体 % は実在しますが、この接続の役はそのメンバーではありません。この役の sequence の既定の権限を外せないので止めます(外す権限のある役で流してください)', creator using errcode = '42501';
        end if;
        execute format('alter default privileges for role %I revoke all on sequences from public, anon, authenticated', creator);
        foreach schema_name in array array['public', 'api'] loop
            if to_regnamespace(schema_name) is not null then
                execute format('alter default privileges for role %I in schema %I revoke all on sequences from public, anon, authenticated', creator, schema_name);
            end if;
        end loop;
    end loop;
    for creator in select unnest(array['supabase_admin']::text[]) loop
        if exists (select 1 from pg_roles where rolname = creator)
            and pg_has_role(current_user, creator::name, 'MEMBER') then
            execute format('alter default privileges for role %I revoke all on sequences from public, anon, authenticated', creator);
            foreach schema_name in array array['public', 'api'] loop
                if to_regnamespace(schema_name) is not null then
                    execute format('alter default privileges for role %I in schema %I revoke all on sequences from public, anon, authenticated', creator, schema_name);
                end if;
            end loop;
        end if;
    end loop;

    select string_agg(format('%s → %s', q.name, q.grantee), ', ' order by q.name, q.grantee)
        into leftovers
      from (
        select c.oid::regclass::text as name,
               (case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee)::text end) as grantee
          from pg_class c
          join pg_namespace n on n.oid = c.relnamespace
          cross join lateral aclexplode(coalesce(c.relacl, acldefault('s', c.relowner))) a
         where c.relkind = 'S'
           and n.nspname in ('public', 'api')
           and not exists (select 1 from pg_depend d where d.classid = 'pg_class'::regclass and d.objid = c.oid and d.deptype = 'e')
           and (a.grantee = 0 or pg_get_userbyid(a.grantee)::text = any(array['anon', 'authenticated']::text[]))
    ) q;
    if leftovers is not null then
        raise exception 'sequence に面のロールか PUBLIC の権限が残っています(外せなかった付与です。所有者の役で外してください): %', leftovers using errcode = '42501';
    end if;
end
$$;
